        visited = {start}
        return dfs_bound(start, [], 0, b, visited)

    def get_initial_bound():
        return manhattan(start, goal)

    bound = get_initial_bound()
    while True:
        result = solve_with_bound(bound)
        if result is not None:
            return result
        if bound > manhattan(start, goal):
            return []
        bound += 1

