        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bidirectional Dijkstra
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        came_from = {}
        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                break
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
                    came_from[v] = u
        return dist, came_from

    # Run Dijkstra from both ends
    dist_s, came_from_s = dijkstra(s, t)
    dist_t, came_from_t = dijkstra(t, s)

    # Try to merge the paths
    if dist_s[t] == float('inf'):
        return -1

    # Reconstruct path from s to t
    path = []
    u = t
    while u != s:
        path.append(u)
        u = came_from_s.get(u, None)
        if u is None:
            break
    if u != s:
        return -1
    path.append(s)
    path.reverse()

    # Reconstruct path from t to s for potential overlap
    path2 = []
    u = s
    while u != t:
        path2.append(u)
        u = came_from_t.get(u, None)
        if u is None:
            break
    if u != t:
        return -1
    path2.append(t)
    path2.reverse()

    # Find common node
    common = None
    for node in path:
        if node in path2:
            common = node
            break

    if common is None:
        return dist_s[t]

    # Calculate total distance
    return dist_s[common] + dist_t[common]

