    dist = [INF] * n
    dist[s] = 0

    # Bucket queue: buckets indexed by distance
    buckets = {}

    # Initialize buckets
    for i in range(n):
        if dist[i] != INF:
            if dist[i] not in buckets:
                buckets[dist[i]] = []
            buckets[dist[i]].append(i)

    # Use a deque to process buckets in order of increasing distance
    queue = deque()
    for d in sorted(buckets.keys()):
        queue.append(d)

    while queue:
        current_dist = queue[0]
        bucket = buckets[current_dist]
        if not bucket:
            queue.popleft()
            continue

        # Process nodes in the current distance bucket
        while bucket:
            u = bucket.pop()
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    # Update distance
                    dist[v] = dist[u] + w
                    # Remove v from its current bucket if it exists
                    if dist[v] in buckets:
                        if v in buckets[dist[v]]:
                            buckets[dist[v]].remove(v)
                    # Add v to the new distance bucket
                    if dist[v] not in buckets:
                        buckets[dist[v]] = []
                    buckets[dist[v]].append(v)
                    # Insert new distance into the queue if not already present
                    if dist[v] not in queue:
                        queue.append(dist[v])

        # Remove current distance from queue if bucket is empty
        if not buckets[current_dist]:
            queue.popleft()

    return dist[t] if dist[t] != INF else -1

